mapper.select:
SELECT n.operator_id AS memberId, AS memberName, COUNT(*) AS doneCount, COALESCE(ROUND(AVG(CASE WHEN n.claim_time IS NOT NULL AND n.done_time IS NOT NULL THEN TIMESTAMPDIFF(SECOND, n.claim_time, n.done_time) END)), 0) AS avgSeconds
WHERE n.deleted = 0 AND n.status = 'done' AND n.operator_id IS NOT NULL AND n.done_time >= CONCAT(#{q.startDate}, ' 00:00:00') AND n.done_time <= CONCAT(#{q.endDate}, ' 23:59:59')
GROUP BY n.operator_id, u.nick_name, u.user_name ORDER BY doneCount DESC, avgSeconds ASC LIMIT #{q.limit}

SELECT s.memberId AS memberId, s.memberName AS memberName, COUNT(DISTINCT s.unitKey) AS totalFrames, COUNT(DISTINCT CASE WHEN s.tagCnt > 0 THEN s.unitKey END) AS labeledFrames, COUNT(DISTINCT CASE WHEN s.tagCnt = 0 THEN s.unitKey END) AS emptyFrames, COALESCE(SUM(s.tagCnt), 0) AS tagCount FROM ( SELECT n.operator_id AS memberId, AS memberName, COALESCE(a.frame_id, a.asset_id, ast.id) AS unitKey,
COUNT(CASE WHEN ast.frame_flag IS NULL OR ast.frame_flag = 'normal' THEN ao.id END) AS tagCnt FROM label_entry_node n INNER JOIN label_task t ON t.id = n.task_id AND t.deleted = 0 INNER JOIN label_project p ON p.id = t.project_id AND p.deleted = 0 INNER JOIN label_asset ast ON ast.entry_id = n.entry_id AND ast.deleted = 0 INNER JOIN label_annotation a ON a.asset_id = ast.id AND a.deleted = 0 LEFT JOIN label_annotation_object ao ON ao.annotation_id = a.id AND ao.deleted = 0 LEFT JOIN sys_user u ON u.user_id = n.operator_id WHERE n.deleted = 0 AND n.status = 'done' AND n.operator_id IS NOT NULL AND n.done_time >= CONCAT(#{q.startDate}, ' 00:00:00') AND n.done_time <= CONCAT(#{q.endDate}, ' 23:59:59')
GROUP BY n.operator_id, u.nick_name, u.user_name, COALESCE(a.frame_id, a.asset_id, ast.id) ) s GROUP BY s.memberId, s.memberName ORDER BY tagCount DESC LIMIT #{q.limit}

SELECT ws.user_id AS memberId, COALESCE(NULLIF(u.nick_name, ''), u.user_name, CONCAT('用户', ws.user_id)) AS memberName, DATE_FORMAT(ws.work_date, '%Y-%m-%d') AS day, COALESCE(SUM(ws.active_seconds), 0) AS seconds, 0 AS doneCount FROM label_work_session ws LEFT JOIN sys_user u ON u.user_id = ws.user_id LEFT JOIN label_task t ON t.id = ws.task_id AND t.deleted = 0 LEFT JOIN label_project p ON p.id = t.project_id AND p.deleted = 0 WHERE ws.deleted = 0 AND ws.work_date >= #{q.startDate} AND ws.work_date <= #{q.endDate} AND (ws.project_id = #{q.projectId} OR p.id = #{q.projectId}) AND ws.task_id = #{q.taskId} AND ws.node_key = #{q.nodeKey}
AND (t.team_id = #{q.teamId} OR p.team_id = #{q.teamId} OR EXISTS (SELECT 1 FROM label_project_team pt WHERE pt.project_id = p.id AND pt.team_id = #{q.teamId} AND pt.deleted = 0))
AND ws.user_id IN #{mid}
GROUP BY ws.user_id, u.nick_name, u.user_name, ws.work_date ORDER BY day ASC

SELECT wn.node_key AS nodeKey, MIN(wn.node_name) AS nodeName, MIN(wn.node_type) AS nodeType FROM label_workflow_node wn INNER JOIN label_project p ON p.id = wn.project_id AND p.deleted = 0 WHERE wn.deleted = 0 AND p.id = #{q.projectId}
AND (p.team_id = #{q.teamId} OR EXISTS (SELECT 1 FROM label_project_team pt WHERE pt.project_id = p.id AND pt.team_id = #{q.teamId} AND pt.deleted = 0))
GROUP BY wn.node_key ORDER BY MIN(wn.sort_order) ASC

SELECT t.id AS id, t.task_name AS name FROM label_task t INNER JOIN label_project p ON p.id = t.project_id AND p.deleted = 0 WHERE t.deleted = 0 AND p.id = #{q.projectId}
AND (t.team_id = #{q.teamId} OR p.team_id = #{q.teamId} OR EXISTS (SELECT 1 FROM label_project_team pt WHERE pt.project_id = p.id AND pt.team_id = #{q.teamId} AND pt.deleted = 0))
ORDER BY t.create_time DESC LIMIT 200

SELECT e.id AS id, COALESCE(NULLIF(e.entry_name, ''), CONCAT('条目#', e.id)) AS name FROM label_data_entry e INNER JOIN label_task t ON t.id = e.task_id AND t.deleted = 0 INNER JOIN label_project p ON p.id = t.project_id AND p.deleted = 0 WHERE e.deleted = 0 AND p.id = #{q.projectId} AND t.id = #{q.taskId}
AND (t.team_id = #{q.teamId} OR p.team_id = #{q.teamId} OR EXISTS (SELECT 1 FROM label_project_team pt WHERE pt.project_id = p.id AND pt.team_id = #{q.teamId} AND pt.deleted = 0))
ORDER BY e.id DESC LIMIT 500

SELECT COALESCE(SUM(active_seconds), 0)
FROM label_work_session
WHERE deleted = 0
  AND user_id = #{userId}
  AND task_id = #{taskId}
  AND node_key = #{nodeKey}
  AND work_date = #{workDate}
